scenes.css:
#rf-root,.hf-root{--x3:#3a3a3a;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 4.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx.tx-iris-out{inset:auto;background:transparent;box-shadow:0 0 0 2400px var(--rf-surface);border-radius:50%;width:2400px;height:2400px;left:calc(50% - 1200px);top:calc(50% - 1200px);animation:tx-iris-out 0.5s cubic-bezier(.76,0,.24,1) 4s both;opacity:0}@keyframes tx-iris-out{from{opacity:1}to{opacity:1;width:0;height:0;left:50%;top:50%}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mbs{position:absolute;inset:0}
.mb{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:0 70px;text-align:center;clip-path:inset(100% 0 0 0);animation:mb-in .5s cubic-bezier(.76,0,.24,1) both}
.mb:first-child{clip-path:none;animation:none}
@keyframes mb-in{to{clip-path:inset(0 0 0 0)}}
.mb span{font-size:200px;font-weight:600;letter-spacing:-.055em;line-height:.9;animation:mb-t .8s cubic-bezier(.16,1,.3,1) both}
@keyframes mb-t{from{transform:translateY(60px);opacity:0}}
.b1{background:var(--rf-bg);color:var(--rf-text)}.b2{background:var(--rf-surface);color:var(--rf-text)}.b3{background:var(--rf-text);color:var(--rf-bg)}.b4{background:var(--rf-accent);color:var(--rf-bg)}
.mf{position:absolute;left:0;right:0;bottom:380px;z-index:99;text-align:center;font:500 30px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;mix-blend-mode:difference;color:#fff}
